// Banco de questoes - Historia (Cap. 8 - A Africa Antiga: diferentes povos) - 5o ano - prova 17/11
window.BANCO = window.BANCO || {};
window.BANCO.historia = [
{n:"f",t:"Nok",q:"Em que continente se desenvolveu a cultura Nok?",a:["Europa","África","Ásia","América"],c:1,e:"A cultura Nok surgiu na África, na região onde hoje fica a Nigéria, no oeste do continente."},
{n:"f",t:"Nok",q:"Em qual país atual ficava a região da cultura Nok?",a:["Egito","Brasil","Nigéria","Etiópia"],c:2,e:"Os vestígios da cultura Nok foram encontrados no centro da atual Nigéria, na África Ocidental."},
{n:"f",t:"Nok",q:"A cultura Nok ficou famosa principalmente por quais objetos?",a:["Esculturas de terracota","Pirâmides de pedra lisa","Navios de madeira pintada","Moedas de ouro e prata"],c:0,e:"Os Nok faziam esculturas de terracota, que é argila (barro) cozida no fogo. Muitas mostram cabeças humanas com penteados caprichados."},
{n:"f",t:"Nok",q:"O que é terracota?",a:["Um tipo de tecido de algodão","Uma pedra preciosa azul","Argila cozida no fogo","Um metal brilhante e mole"],c:2,e:"Terracota quer dizer 'terra cozida': é o barro moldado e depois queimado no forno, ficando duro como um vaso."},
{n:"f",t:"Nok",q:"Que metal o povo Nok aprendeu a trabalhar, fazendo ferramentas e armas?",a:["Ferro","Alumínio","Titânio","Aço inox"],c:0,e:"Os Nok estão entre os primeiros povos ao sul do deserto do Saara a trabalhar o ferro, fazendo enxadas, machados e armas."},
{n:"f",t:"Reinos e impérios africanos",q:"A África é um país ou um continente?",a:["Um país com uma só língua","Uma cidade muito grande e antiga","Um continente com muitos países e povos","Uma ilha no meio do oceano Pacífico"],c:2,e:"A África é um continente enorme, com dezenas de países, centenas de povos e mais de mil línguas diferentes."},
{n:"f",t:"Reinos e impérios africanos",q:"Quem governava um reino?",a:["Um rei ou uma rainha","Um presidente eleito","Um prefeito da cidade","Um grupo de professores"],c:0,e:"Reino é o território governado por um rei ou uma rainha. Na África antiga existiram muitos reinos diferentes."},
{n:"f",t:"Reinos e impérios africanos",q:"Na África antiga, vivia um só povo ou muitos povos diferentes?",a:["Um só povo, todos com os mesmos costumes","Nenhum povo, o continente era vazio","Só povos que tinham vindo da Europa","Muitos povos, com línguas e costumes diferentes"],c:3,e:"A África sempre foi muito diversa: cada povo tinha sua língua, sua religião, seu jeito de morar e de governar."},
{n:"f",t:"Reinos e impérios africanos",q:"Qual destes era um reino da África antiga?",a:["Reino de Portugal","Reino de Cuxe","Império Romano","Império Inca"],c:1,e:"Cuxe foi um reino africano que ficava ao sul do Egito, às margens do rio Nilo. Portugal e Roma ficam na Europa; os incas, na América."},
{n:"f",t:"Reinos e impérios africanos",q:"Como os historiadores descobrem como viviam povos que não deixaram textos escritos?",a:["Inventando histórias sobre eles","Estudando vestígios achados por arqueólogos","Lendo os jornais que eles imprimiam","Assistindo aos filmes que eles gravaram"],c:1,e:"Os arqueólogos escavam e estudam vestígios — esculturas, ferramentas, restos de casas — que contam como os povos viviam."},
{n:"f",t:"Reino de Cuxe",q:"O Reino de Cuxe ficava ao sul de qual reino famoso?",a:["Egito","Roma","Grécia","China"],c:0,e:"Cuxe ficava na Núbia, logo ao sul do Egito. Os dois reinos eram vizinhos e às vezes amigos, às vezes inimigos."},
{n:"f",t:"Reino de Cuxe",q:"Às margens de qual rio se desenvolveu o Reino de Cuxe?",a:["Amazonas","Nilo","Tietê","Mississípi"],c:1,e:"Assim como o Egito, Cuxe nasceu às margens do rio Nilo, que dava água e terra boa para plantar."},
{n:"f",t:"Reino de Cuxe",q:"Em qual país atual ficava a maior parte do Reino de Cuxe?",a:["Nigéria","Marrocos","África do Sul","Sudão"],c:3,e:"O antigo Reino de Cuxe ficava na região da Núbia, onde hoje é o Sudão, ao sul do Egito."},
{n:"f",t:"Reino de Cuxe",q:"Qual era o nome da região onde ficava o Reino de Cuxe?",a:["Núbia","Saara Ocidental","Mesopotâmia","Patagônia"],c:0,e:"A região ao sul do Egito, ao longo do Nilo, se chama Núbia. Foi lá que floresceu o Reino de Cuxe."},
{n:"f",t:"Reino de Cuxe",q:"Que riqueza muito valiosa existia em grande quantidade no Reino de Cuxe?",a:["Petróleo","Café","Ouro","Borracha"],c:2,e:"Cuxe tinha muitas minas de ouro. Esse ouro era desejado pelos egípcios e foi uma das grandes riquezas do reino. ✨"},
{n:"f",t:"Reino de Cuxe",q:"Assim como os egípcios, os cuxitas também construíram...",a:["arranha-céus","pirâmides","castelos medievais","estradas de ferro"],c:1,e:"Os cuxitas construíram muitas pirâmides, principalmente em Méroe. Elas são menores e mais pontudas que as egípcias."},
{n:"f",t:"Candaces",q:"Quem eram as candaces?",a:["Sacerdotisas dos templos do Egito","Rainhas-mães do Reino de Cuxe","Comerciantes do porto de Axum","Artesãs das esculturas Nok"],c:1,e:"Candace era o título das rainhas-mães de Cuxe, mulheres com muito poder no governo do reino."},
{n:"f",t:"Candaces",q:"As candaces tinham pouco ou muito poder no Reino de Cuxe?",a:["Nenhum poder, só obedeciam aos reis","Pouco poder, só cuidavam do palácio","Muito poder: algumas governaram sozinhas","Só mandavam nas crianças da família real"],c:2,e:"As candaces eram muito poderosas: ajudavam a governar e algumas reinaram sozinhas, comandando até exércitos. 👑"},
{n:"f",t:"Candaces",q:"A palavra 'candace' era usada para se referir a...",a:["uma rainha de Cuxe","um tipo de barco","um deus egípcio","uma moeda de ouro"],c:0,e:"Candace era um título, como 'rainha'. Era dado às mulheres poderosas da família real de Cuxe."},
{n:"f",t:"Candaces",q:"Por que as candaces são chamadas de 'rainhas-mães'?",a:["Porque adotavam todas as crianças do reino","Porque eram mães dos reis e tinham grande poder","Porque cuidavam das escolas de Cuxe","Porque eram mães dos imperadores romanos"],c:1,e:"Elas eram as mães dos reis. Em Cuxe, a mãe do rei tinha enorme importância e participava das decisões do governo."},
{n:"f",t:"Império de Axum",q:"Onde ficava o Império de Axum?",a:["No sul da Europa, perto da Itália","No nordeste da África, na atual Etiópia","No oeste da Ásia, perto da China","Na América do Sul, perto do Brasil"],c:1,e:"Axum ficava no nordeste da África, nas terras altas da atual Etiópia e da Eritreia, perto do mar Vermelho."},
{n:"f",t:"Império de Axum",q:"Perto de qual mar ficava o Império de Axum?",a:["Mar Vermelho","Mar do Norte","Mar Báltico","Mar do Caribe"],c:0,e:"Axum ficava perto do mar Vermelho e usava o porto de Adúlis para fazer comércio com outros povos."},
{n:"f",t:"Império de Axum",q:"Qual atividade deixou o Império de Axum muito rico?",a:["A pesca de baleias","O comércio com outros povos","A venda de carros","A mineração de carvão"],c:1,e:"Axum ficou rico com o comércio: vendia marfim, ouro e incenso e comprava tecidos, vinho e objetos de outros povos."},
{n:"f",t:"Império de Axum",q:"Que objeto o Império de Axum fabricava, mostrando que era rico e organizado?",a:["Celulares","Moedas próprias","Bicicletas","Livros impressos"],c:1,e:"Axum cunhava suas próprias moedas de ouro, prata e bronze — foi um dos primeiros reinos africanos a fazer isso. 🪙"},
{n:"m",t:"Nok",q:"Por que dizemos que a cultura Nok é muito antiga?",a:["Porque existiu há uns 50 anos","Porque surgiu há mais de 2 mil anos","Porque foi criada pelos portugueses","Porque surgiu depois do ano 1900"],c:1,e:"A cultura Nok floresceu há mais de 2 mil anos, muito antes de os europeus chegarem à África."},
{n:"m",t:"Nok",q:"O que as esculturas Nok costumam mostrar com muitos detalhes?",a:["Carros, rodas e máquinas","Rostos humanos, penteados e joias","Mapas das cidades e estradas","Letras, números e calendários"],c:1,e:"As cabeças de terracota Nok têm penteados elaborados, enfeites e olhos marcantes — um retrato de como aquelas pessoas se arrumavam."},
{n:"m",t:"Nok",q:"Como é o formato dos olhos de muitas esculturas Nok?",a:["Quadrados e pintados de azul-claro","Fechados, como se a pessoa dormisse","Triangulares ou em meia-lua, com a pupila furada","Feitos com pedras preciosas coladas"],c:2,e:"Uma marca das esculturas Nok são os olhos grandes, triangulares ou em meia-lua, com um furinho no lugar da pupila."},
{n:"m",t:"Nok",q:"Por que conhecer o ferro foi importante para o povo Nok?",a:["Permitiu fazer ferramentas melhores para plantar","O ferro derretido servia de alimento","Com o ferro faziam as esculturas de barro","O ferro era usado como dinheiro de papel"],c:0,e:"Enxadas e machados de ferro são mais fortes: ajudavam a derrubar mato, plantar e caçar, e assim produzir mais alimento."},
{n:"m",t:"Nok",q:"De onde vem o nome 'Nok'?",a:["Do nome de um rei muito famoso","Do vilarejo onde as primeiras peças foram achadas","De uma palavra que significa 'ferro'","Do nome de um rio que passa no Egito"],c:1,e:"Nok é o nome de um vilarejo na Nigéria onde as primeiras peças foram achadas, no século XX. Por isso a cultura ganhou esse nome."},
{n:"m",t:"Reinos e impérios africanos",q:"Qual é a diferença entre um reino e um império?",a:["Não existe diferença nenhuma entre os dois","O império domina vários povos e territórios","O reino é sempre muito maior que o império","O império não tem nenhum governante"],c:1,e:"Um império é como um 'reino gigante': ele conquista e governa vários povos e terras diferentes, muitas vezes cobrando tributos deles."},
{n:"m",t:"Reinos e impérios africanos",q:"O que era o tributo cobrado por muitos reinos e impérios africanos?",a:["Uma festa religiosa feita uma vez por ano","Um pagamento dos povos dominados ao governante","Um tipo de escultura feita de barro cozido","Uma estrada usada pelos comerciantes"],c:1,e:"Tributo é um pagamento (em produtos, ouro, animais ou trabalho) que os povos dominados entregavam ao rei ou imperador."},
{n:"m",t:"Reinos e impérios africanos",q:"Quem eram os griôs, importantes em muitos povos africanos?",a:["Guerreiros que lutavam montados a cavalo","Contadores de histórias que guardavam a memória do povo","Arquitetos que construíam pirâmides de pedra","Comerciantes que vendiam sal no deserto"],c:1,e:"Os griôs guardavam a história do povo na memória e a transmitiam oralmente, contando, cantando e recitando."},
{n:"m",t:"Reinos e impérios africanos",q:"Qual destas fontes ajuda a conhecer a história de povos africanos que não usavam a escrita?",a:["A tradição oral, passada de geração em geração","Os livros que eles mesmos escreveram e imprimiram","As mensagens que deixaram nas redes sociais","As notícias publicadas nos jornais da época"],c:0,e:"Muitos povos africanos guardavam sua história na tradição oral: histórias, cantos e provérbios contados dos mais velhos para os mais novos."},
{n:"m",t:"Reinos e impérios africanos",q:"Por que muitos reinos africanos antigos se formaram perto de rios?",a:["Porque os rios afastavam todos os inimigos","Porque havia água, terra fértil e caminho para o comércio","Porque era proibido por lei morar longe dos rios","Porque todo rio da África tinha ouro nas margens"],c:1,e:"Rios como o Nilo davam água para beber e plantar, peixes e um caminho para barcos levarem mercadorias."},
{n:"m",t:"Reino de Cuxe",q:"Quais foram cidades importantes (capitais) do Reino de Cuxe?",a:["Kerma, Napata e Méroe","Roma, Atenas e Esparta","Cairo, Lagos e Luanda","Adúlis, Axum e Gondar"],c:0,e:"Ao longo de sua longa história, Cuxe teve como capitais Kerma, depois Napata e, por fim, Méroe."},
{n:"m",t:"Reino de Cuxe",q:"O que aconteceu quando os reis de Cuxe conquistaram o Egito?",a:["Destruíram todas as pirâmides","Governaram o Egito como faraós","Levaram os egípcios para a Europa","Proibiram o uso do rio Nilo"],c:1,e:"Por volta de 730 a.C., os reis cuxitas conquistaram o Egito e governaram como faraós por quase cem anos. 👑"},
{n:"m",t:"Reino de Cuxe",q:"Que produtos os cuxitas vendiam ou trocavam com os egípcios?",a:["Ouro, marfim, ébano e peles de animais","Café, açúcar, algodão e cacau","Carros, petróleo, plástico e vidro","Papel, seda, porcelana e chá"],c:0,e:"Cuxe oferecia riquezas da África: ouro, marfim (dente de elefante), ébano (madeira escura) e peles. Isso movimentava o comércio com o Egito."},
{n:"m",t:"Reino de Cuxe",q:"Por que os egípcios tinham tanto interesse no Reino de Cuxe?",a:["Porque Cuxe tinha neve e montanhas geladas","Porque Cuxe tinha ouro e produtos do interior da África","Porque queriam aprender a língua portuguesa","Porque Cuxe tinha o único porto do oceano"],c:1,e:"Cuxe era rico em ouro e ficava no caminho de mercadorias vindas do interior da África, como marfim e ébano."},
{n:"m",t:"Reino de Cuxe",q:"Méroe, capital de Cuxe, ficou famosa por produzir muito...",a:["vidro colorido","ferro","papel","chocolate"],c:1,e:"Em Méroe havia muitos fornos para derreter minério e fazer ferro. Até hoje existem montes de escória (restos da fundição) por lá."},
{n:"m",t:"Reino de Cuxe",q:"Comparadas às do Egito, como são as pirâmides de Cuxe?",a:["Muito maiores e mais largas","Feitas de madeira e palha","Menores e mais pontiagudas","Redondas como uma bola"],c:2,e:"As pirâmides de Cuxe (em Méroe, por exemplo) são menores e mais inclinadas, bem pontudas. E existem mais delas no Sudão do que no Egito!"},
{n:"m",t:"Candaces",q:"Amanirenas foi uma candace famosa porque...",a:["construiu a primeira pirâmide do mundo inteiro","enfrentou os romanos e conseguiu um acordo de paz","inventou a escrita hieroglífica dos egípcios","foi a primeira mulher a governar o Império Inca"],c:1,e:"Amanirenas liderou os cuxitas contra os romanos e depois negociou um acordo de paz vantajoso com o imperador Augusto."},
{n:"m",t:"Candaces",q:"Contra qual grande império a candace Amanirenas lutou?",a:["Império Romano","Império Inca","Império Chinês","Império Português"],c:0,e:"Os romanos dominavam o Egito e tentaram avançar sobre Cuxe. Amanirenas resistiu e conseguiu um acordo de paz."},
{n:"m",t:"Candaces",q:"O que a história das candaces mostra sobre a sociedade de Cuxe?",a:["Que as mulheres eram proibidas de sair de casa","Que as mulheres podiam ter grande poder político","Que só os sacerdotes egípcios mandavam no reino","Que Cuxe vivia sem nenhum tipo de governo"],c:1,e:"As candaces provam que, em Cuxe, mulheres podiam governar, comandar exércitos e tomar decisões importantes."},
{n:"m",t:"Candaces",q:"Como as candaces costumavam ser representadas em templos e monumentos?",a:["Fortes, com joias e símbolos de poder","Escondidas atrás dos reis, bem pequenas","Como meninas brincando no rio Nilo","Sempre de costas, sem mostrar o rosto"],c:0,e:"Nas imagens de Cuxe, as candaces aparecem fortes, enfeitadas com joias e às vezes segurando armas — sinal de poder e prestígio."},
{n:"m",t:"Império de Axum",q:"Qual era o principal porto do Império de Axum no mar Vermelho?",a:["Adúlis","Alexandria","Lisboa","Méroe"],c:0,e:"Adúlis era o grande porto de Axum. Por ali chegavam e saíam mercadorias de e para Roma, Arábia e Índia. ⛵"},
{n:"m",t:"Império de Axum",q:"Que religião o rei Ezana, de Axum, adotou no século IV?",a:["Budismo","Cristianismo","Islamismo","Religião dos deuses gregos"],c:1,e:"O rei Ezana se converteu ao cristianismo por volta do ano 330, e Axum se tornou um dos primeiros reinos cristãos do mundo. ✝️"},
{n:"m",t:"Império de Axum",q:"O que são as estelas de Axum?",a:["Moedas de prata com o rosto do rei","Enormes monumentos de pedra esculpida","Barcos usados para cruzar o mar Vermelho","Pinturas feitas em folhas de papiro"],c:1,e:"As estelas são enormes blocos de pedra talhados, alguns com mais de 20 metros, ligados aos túmulos de reis e nobres."},
{n:"m",t:"Império de Axum",q:"Com quais povos Axum fazia comércio?",a:["Só com os povos indígenas da América","Com romanos, egípcios, árabes e indianos","Com nenhum povo, pois vivia isolado","Só com os povos que moravam na Europa"],c:1,e:"Graças ao mar Vermelho, Axum comerciava com o Império Romano, o Egito, a Arábia e até a Índia."},
{n:"d",t:"Nok",q:"Os Nok não deixaram textos escritos. Então, como sabemos que eles dominavam a metalurgia do ferro?",a:["Porque eles contaram tudo aos portugueses","Porque foram achados restos de fornos e objetos de ferro","Porque isso está escrito em hieróglifos egípcios","Porque as esculturas têm frases gravadas sobre isso"],c:1,e:"Escavações acharam restos de fornos de fundição e pedaços de ferro. Esses vestígios materiais são a prova."},
{n:"d",t:"Nok",q:"Uma escultura Nok de terracota foi encontrada com penteado elaborado e colares. O que ela nos ajuda a entender?",a:["Que os Nok usavam as mesmas roupas de hoje","Como aquelas pessoas se enfeitavam","Que os Nok moravam no sul da Europa","Que os Nok cunhavam moedas de ouro"],c:1,e:"As esculturas são como 'fotos' do passado: mostram penteados, joias e adornos, revelando costumes e a importância da aparência."},
{n:"d",t:"Nok",q:"Por que a metalurgia do ferro ajudou a cultura Nok a crescer?",a:["Ferramentas melhores permitiram produzir mais alimento","O ferro obrigou o povo a virar nômade de novo","O ferro substituiu completamente o barro nas casas","O ferro era trocado por pirâmides com o Egito"],c:0,e:"Com ferramentas de ferro dava para limpar terrenos e plantar mais. Mais comida significa mais gente e aldeias maiores."},
{n:"d",t:"Nok",q:"Qual afirmação sobre a cultura Nok está correta?",a:["Foi criada pelos egípcios para enfeitar pirâmides","Fazia esculturas de terracota e trabalhava o ferro","Era uma província do Império de Axum","Usava moedas de ouro com o rosto dos reis"],c:1,e:"Terracota e ferro são as duas marcas da cultura Nok, que viveu no território da atual Nigéria."},
{n:"d",t:"Reinos e impérios africanos",q:"Muitas pessoas pensavam que a África não tinha história antes da chegada dos europeus. Estudar Nok, Cuxe e Axum mostra que...",a:["essa ideia estava certa desde o começo","a África teve reinos, impérios e culturas antigas","o Egito foi o único reino que existiu na África","os povos africanos não sabiam trabalhar metais"],c:1,e:"Essa ideia era preconceito. Povos como Nok, Cuxe e Axum tinham governo, comércio, arte, escrita e tecnologia muito antes dos europeus chegarem."},
{n:"d",t:"Reinos e impérios africanos",q:"Axum é chamado de 'império' e não apenas de 'reino'. Por quê?",a:["Porque nunca teve um rei no governo","Porque dominou outros povos e territórios","Porque era menor do que uma aldeia","Porque ficava no continente europeu"],c:1,e:"Axum estendeu seu poder sobre outros povos e terras — até sobre Cuxe e partes da Arábia. Dominar vários povos é o que caracteriza um império."},
{n:"d",t:"Reinos e impérios africanos",q:"Ordene do mais antigo para o mais recente:\n(1) o rei Ezana, de Axum, adota o cristianismo\n(2) reis de Cuxe governam o Egito como faraós\n(3) a candace Amanirenas enfrenta os romanos",a:["2, 3, 1","1, 2, 3","3, 1, 2","2, 1, 3"],c:0,e:"Primeiro os cuxitas governaram o Egito (por volta de 730 a.C.); depois Amanirenas enfrentou Roma (século I a.C.); por fim Ezana virou cristão (século IV d.C.)."},
{n:"d",t:"Reinos e impérios africanos",q:"O que os reinos de Cuxe e Axum tinham em comum?",a:["Ficavam no nordeste da África e enriqueceram com o comércio","Ficavam na América do Sul e usavam moedas de papel","Nunca tiveram nenhum contato com outros povos","Foram governados pelos romanos durante toda a história"],c:0,e:"Cuxe (no atual Sudão) e Axum (na atual Etiópia) eram vizinhos no nordeste da África e ficaram ricos comerciando ouro, marfim e outros produtos."},
{n:"d",t:"Reino de Cuxe",q:"Os cuxitas adotaram alguns costumes egípcios, como construir pirâmides e adorar o deus Amon. Isso mostra que...",a:["os dois povos nunca tiveram nenhum contato","houve trocas culturais entre Cuxe e o Egito","os cuxitas eram romanos que mudaram de nome","o Egito ficava bem ao sul do Reino de Cuxe"],c:1,e:"Vizinhos que comerciam e convivem trocam ideias, crenças e costumes. Cuxe recebeu influências do Egito, mas manteve tradições próprias."},
{n:"d",t:"Reino de Cuxe",q:"Os cuxitas criaram uma escrita própria, a escrita meroítica. O que é curioso sobre ela hoje?",a:["É ensinada em todas as escolas do Brasil","Lemos os sinais, mas ainda não entendemos bem a língua","Foi copiada letra por letra do alfabeto português","Só aparece gravada nas moedas de Axum"],c:1,e:"Sabemos como os sinais meroíticos soam, mas a língua ainda não foi totalmente compreendida. É um mistério que os cientistas tentam desvendar! 🔍"},
{n:"d",t:"Reino de Cuxe",q:"Montes de escória (restos da fundição de metal) foram encontrados em Méroe. O que eles indicam?",a:["Que ali havia grande produção de ferro","Que ali existiu uma praia de mar aberto","Que ali se fabricava vidro para janelas","Que a cidade foi destruída por um vulcão"],c:0,e:"Escória é o resto que sobra ao derreter o minério para tirar o metal. Muita escória = muita produção de ferro."},
{n:"d",t:"Reino de Cuxe",q:"Como terminou o poder do Reino de Cuxe, por volta do século IV?",a:["Foi conquistado pelos navegadores portugueses","Enfraquecido, foi dominado pelo Império de Axum","Virou uma província do distante Império Inca","Desapareceu por causa de uma grande nevasca"],c:1,e:"Por volta do ano 350, já enfraquecido, Cuxe foi atacado e dominado pelo Império de Axum, do rei Ezana."},
{n:"d",t:"Reino de Cuxe",q:"Por que o rio Nilo era tão importante para o Reino de Cuxe?",a:["Dava água, terra fértil e caminho para o comércio","Separava Cuxe da Europa e o protegia de tudo","Nele se pescavam baleias e grandes tubarões","Impedia qualquer contato com o povo egípcio"],c:0,e:"O Nilo era a 'estrada' e a 'fazenda' de Cuxe: água para plantar, peixes, e barcos levando mercadorias até o Egito."},
{n:"d",t:"Reino de Cuxe",q:"Os egípcios chamavam a Núbia de 'Terra do Arco'. Isso porque os núbios eram famosos como...",a:["arqueiros habilidosos","pescadores de baleias","navegadores do Atlântico","construtores de navios"],c:0,e:"Os arqueiros núbios eram tão bons que até trabalharam nos exércitos egípcios. 🏹"},
{n:"d",t:"Candaces",q:"Depois de enfrentar os romanos, a candace Amanirenas negociou com o imperador Augusto. Qual foi o resultado?",a:["Cuxe virou uma província romana","Um acordo de paz favorável a Cuxe","Amanirenas foi morar em Roma","Os romanos destruíram Méroe"],c:1,e:"O acordo de paz foi bom para Cuxe: os romanos recuaram e deixaram de exigir tributos do reino."},
{n:"d",t:"Candaces",q:"Uma cabeça de bronze de uma estátua do imperador romano Augusto foi achada enterrada sob a escada de um templo em Méroe. O que isso pode significar?",a:["Que os cuxitas adoravam Augusto como um deus","Era um troféu: quem subia a escada pisava no inimigo","Que o imperador Augusto morou em Méroe","Que foram os romanos que construíram o templo"],c:1,e:"A cabeça foi levada como troféu de guerra e enterrada onde todos pisariam — um jeito de mostrar a vitória de Cuxe sobre Roma."},
{n:"d",t:"Candaces",q:"Em Cuxe, a mãe do rei participava da escolha e do governo do filho. Isso mostra que...",a:["a família da mãe era muito importante na política","o rei de Cuxe não tinha nenhuma família","as mulheres não podiam dar opinião no reino","o poder vinha só dos sacerdotes do Egito"],c:0,e:"Em Cuxe a família da mãe pesava muito: as rainhas-mães ajudavam a garantir quem seria rei e a governar o reino."},
{n:"d",t:"Candaces",q:"Comparando Cuxe com muitos reinos antigos em que só homens governavam, o que as candaces tinham de especial?",a:["Eram proibidas de ter filhos","Podiam reinar e comandar exércitos","Moravam sempre fora do reino","Só cuidavam dos templos egípcios"],c:1,e:"Nem todo reino antigo aceitava mulheres no poder. Em Cuxe, as candaces governavam, guerreavam e negociavam com outros impérios."},
{n:"d",t:"Império de Axum",q:"Axum cunhava moedas de ouro, prata e bronze. O que isso indica?",a:["Que era um império rico, com comércio forte","Que Axum não fazia comércio com ninguém","Que as moedas eram só enfeites de cabelo","Que as moedas vinham todas da América"],c:0,e:"Poucos reinos do mundo cunhavam moedas de ouro naquela época. Isso mostra riqueza e muito comércio com outros povos."},
{n:"d",t:"Império de Axum",q:"A escrita ge'ez, criada em Axum, é usada até hoje. Onde?",a:["Nas placas de trânsito das cidades do Brasil","Em textos religiosos da Igreja da Etiópia","Nas moedas que circulam no Império Romano","Nos hieróglifos pintados nas pirâmides do Egito"],c:1,e:"O ge'ez continua vivo nas cerimônias da Igreja Ortodoxa Etíope, e dele derivam escritas usadas hoje na Etiópia e na Eritreia, como a do amárico."},
{n:"d",t:"Império de Axum",q:"Um grande obelisco de Axum foi levado para a Itália em 1937. O que aconteceu depois?",a:["Foi destruído e nunca mais encontrado","Foi devolvido à Etiópia em 2005","Foi vendido para um museu do Brasil","Continua até hoje numa praça de Roma"],c:1,e:"O obelisco ficou décadas em Roma, mas foi devolvido à Etiópia em 2005 e reerguido em Axum. A devolução valorizou a história africana."},
{n:"d",t:"Império de Axum",q:"Por que a localização de Axum, perto do mar Vermelho, foi tão importante?",a:["Permitia caçar baleias e vender seu óleo","Punha Axum na rota de comércio com Roma, Arábia e Índia","O mar protegia Axum de qualquer chuva forte","O mar Vermelho ligava Axum diretamente à América"],c:1,e:"O mar Vermelho era uma 'avenida' do comércio antigo. Controlando o porto de Adúlis, Axum lucrava com as mercadorias que passavam por ali."},
{n:"f",t:"Nok",q:"As esculturas Nok eram feitas principalmente de qual material?",a:["Mármore","Barro cozido","Vidro","Plástico"],c:1,e:"Elas eram feitas de barro (argila) cozido no fogo, a terracota. Por isso resistiram por mais de 2 mil anos."},
{n:"f",t:"Nok",q:"A cultura Nok ficava em qual parte da África?",a:["No norte, junto ao mar Mediterrâneo","No oeste, na África Ocidental","No extremo sul, perto do Cabo","Numa ilha do oceano Índico"],c:1,e:"A cultura Nok ficava na África Ocidental, no território da atual Nigéria."},
{n:"f",t:"Nok",q:"Quem estuda objetos antigos, como as esculturas Nok, para descobrir como os povos viviam?",a:["O arqueólogo","O astronauta","O bombeiro","O carteiro"],c:0,e:"O arqueólogo escava o solo e estuda objetos antigos para entender o passado. 🔍"},
{n:"f",t:"Nok",q:"Muitas esculturas Nok representam...",a:["cabeças e figuras humanas","aviões, foguetes e carros","letras e números","mapas de estradas e cidades"],c:0,e:"As peças mais famosas são cabeças humanas de terracota, com penteados e enfeites caprichados."},
{n:"f",t:"Reinos e impérios africanos",q:"Quem governava um império?",a:["Um imperador ou uma imperatriz","Um presidente eleito pelo povo","O professor mais velho da aldeia","Ninguém, pois não havia governo"],c:0,e:"O império era governado por um imperador ou imperatriz, que mandava em vários povos e territórios."},
{n:"f",t:"Reinos e impérios africanos",q:"Qual destes impérios existiu na África antiga?",a:["Império de Axum","Império Romano","Império Asteca","Império Japonês"],c:0,e:"Axum foi um grande império do nordeste da África. Roma ficava na Europa, os astecas na América e o Japão na Ásia."},
{n:"f",t:"Reinos e impérios africanos",q:"O que é tradição oral?",a:["Saberes passados pela fala, de pessoa para pessoa","Textos guardados em livros de biblioteca","Leis gravadas em grandes placas de pedra","Desenhos pintados nas paredes das cavernas"],c:0,e:"Tradição oral é tudo o que um povo ensina falando: histórias, cantos, provérbios, conhecimentos dos mais velhos."},
{n:"f",t:"Reinos e impérios africanos",q:"Qual rio foi muito importante para os povos do nordeste da África, como egípcios e cuxitas?",a:["Rio Nilo","Rio Amazonas","Rio Danúbio","Rio Paraná"],c:0,e:"O Nilo é o rio mais famoso da África: atravessa o Sudão e o Egito e deu vida a reinos como Cuxe e Egito."},
{n:"f",t:"Reino de Cuxe",q:"Quem eram os cuxitas?",a:["Os habitantes do Reino de Cuxe","Os soldados do Império Romano","Os moradores da cidade de Roma","Os artesãos da cultura Nok"],c:0,e:"Cuxita é quem nasceu ou vivia no Reino de Cuxe, na Núbia."},
{n:"f",t:"Reino de Cuxe",q:"Os reinos de Cuxe e do Egito eram...",a:["vizinhos","muito distantes","o mesmo reino","ilhas"],c:0,e:"Cuxe ficava logo ao sul do Egito, os dois às margens do Nilo. Eram vizinhos!"},
{n:"f",t:"Reino de Cuxe",q:"Qual destas cidades foi capital do Reino de Cuxe?",a:["Méroe","Lisboa","Atenas","Paris"],c:0,e:"Méroe foi a capital de Cuxe em sua fase final, cheia de pirâmides e de fornos de ferro."},
{n:"f",t:"Reino de Cuxe",q:"Em que país atual podemos visitar hoje as pirâmides de Méroe?",a:["Sudão","Brasil","México","Grécia"],c:0,e:"As pirâmides de Méroe ficam no Sudão, onde existia o Reino de Cuxe. O Sudão tem mais pirâmides do que o Egito!"},
{n:"f",t:"Reino de Cuxe",q:"O marfim, um dos produtos de Cuxe, vem...",a:["das presas do elefante","do chifre de um rinoceronte","das penas de um avestruz","da casca de uma árvore rara"],c:0,e:"Marfim é o material das presas (dentes grandes) do elefante. Era muito valioso no comércio antigo — hoje a caça de elefantes é proibida para protegê-los. 🐘"},
{n:"f",t:"Candaces",q:"As candaces governavam em qual reino?",a:["Reino de Cuxe","Reino de Portugal","Império Romano","Império Inca"],c:0,e:"As candaces eram as rainhas-mães de Cuxe, o reino da Núbia ao sul do Egito."},
{n:"f",t:"Candaces",q:"Amanirenas foi uma...",a:["candace (rainha) de Cuxe","imperatriz do Império Romano","faraó do Egito","artesã da cultura Nok"],c:0,e:"Amanirenas foi uma candace guerreira de Cuxe que enfrentou os romanos."},
{n:"f",t:"Candaces",q:"Algumas candaces, além de governar, também...",a:["comandaram exércitos","pilotaram aviões","escreveram em português","moraram na Europa"],c:0,e:"Algumas candaces lideraram os exércitos de Cuxe em guerras, como Amanirenas contra os romanos. ⚔️"},
{n:"f",t:"Candaces",q:"O título de candace era dado a...",a:["mulheres da família real","crianças da aldeia","soldados romanos","comerciantes de Axum"],c:0,e:"Candace era um título feminino: as rainhas e rainhas-mães de Cuxe."},
{n:"f",t:"Império de Axum",q:"Em qual país atual fica a cidade de Axum?",a:["Etiópia","Argentina","Nigéria","Índia"],c:0,e:"Axum é uma cidade da Etiópia até hoje, e guarda os restos do antigo império."},
{n:"f",t:"Império de Axum",q:"O que Axum vendia para outros povos?",a:["Marfim, ouro e incenso","Café, soja e laranja","Carros, motos e celulares","Trigo, uva e vinho do Porto"],c:0,e:"Axum exportava produtos valiosos da África, como marfim, ouro e incenso (resina perfumada usada em cerimônias)."},
{n:"f",t:"Império de Axum",q:"Qual rei de Axum se tornou cristão?",a:["Ezana","Augusto","Ramsés","Júlio César"],c:0,e:"O rei Ezana adotou o cristianismo no século IV. Augusto e Júlio César eram romanos; Ramsés era faraó do Egito."},
{n:"f",t:"Império de Axum",q:"Os grandes monumentos de pedra de Axum, altos e finos, são chamados de...",a:["estelas (ou obeliscos)","pirâmides de degraus","castelos de muralha","torres de tijolo cru e palha"],c:0,e:"As estelas, também chamadas de obeliscos, são pedras gigantes, altas e finas, esculpidas em um só bloco."},
{n:"f",t:"Império de Axum",q:"As moedas de Axum eram feitas de...",a:["ouro, prata e bronze","papel e plástico","madeira e barro","conchas e pedras do rio"],c:0,e:"Axum cunhava moedas de ouro, prata e bronze, usadas no comércio com outros povos."},
{n:"f",t:"Império de Axum",q:"Axum ficava numa região de...",a:["terras altas (planalto)","geleiras e neve eterna","ilhas no meio do oceano","floresta amazônica"],c:0,e:"Axum ficava nas terras altas do planalto da Etiópia, perto do mar Vermelho."},
{n:"m",t:"Nok",q:"Por que a cultura Nok é considerada uma das mais antigas da África Ocidental?",a:["Porque seus vestígios têm mais de 2 mil anos","Porque foi fundada pelos romanos no ano 1500","Porque surgiu muito depois do Império de Axum","Porque ainda existe do mesmo jeito hoje"],c:0,e:"As peças e os fornos Nok foram datados de mais de 2 mil anos atrás, o que coloca essa cultura entre as mais antigas da região."},
{n:"m",t:"Nok",q:"Como os Nok produziam ferro?",a:["Derretendo minério em fornos muito quentes","Pescando pedaços de ferro puro no fundo do rio","Comprando ferro pronto dos portugueses","Recolhendo ferro que caía das nuvens"],c:0,e:"Eles aqueciam o minério (pedra com ferro) em fornos até separar o metal. Isso exige muito conhecimento e fogo bem forte! 🔥"},
{n:"m",t:"Nok",q:"Para que provavelmente serviam as esculturas Nok, segundo os pesquisadores?",a:["Para rituais ou para lembrar os antepassados","Como tijolos para levantar as paredes das casas","Como pesos de balança usados nos mercados","Como moedas para comprar ferro de outros povos"],c:0,e:"Não temos certeza, mas muitos pesquisadores acreditam que as esculturas tinham uso religioso ou lembravam antepassados importantes."},
{n:"m",t:"Nok",q:"Os Nok viviam principalmente de quê?",a:["Agricultura, em aldeias","Pesca em alto-mar, em navios","Comércio de petróleo","Mineração de diamantes para a Europa"],c:0,e:"Os Nok viviam em aldeias e plantavam cereais, usando ferramentas de ferro e pedra. Também caçavam e criavam alguns animais."},
{n:"m",t:"Reinos e impérios africanos",q:"Por que é errado imaginar a África como um lugar com um só povo e uma só cultura?",a:["Porque lá viviam muitos povos, com culturas diferentes","Porque lá todos falavam a mesma língua, o português","Porque a África é um país pequeno, com uma só cidade","Porque todos os africanos eram do mesmo reino, Cuxe"],c:0,e:"A África tem enorme diversidade: são muitos povos, línguas, religiões e formas de governo, desde a Antiguidade."},
{n:"m",t:"Reinos e impérios africanos",q:"Os reinos africanos antigos ficavam ricos principalmente com...",a:["a agricultura, a mineração e o comércio","a venda de aparelhos eletrônicos","o turismo de pessoas de outros planetas","a exploração de petróleo no fundo do mar"],c:0,e:"Plantar, extrair metais como ouro e ferro e comerciar com outros povos eram as grandes fontes de riqueza dos reinos africanos."},
{n:"m",t:"Reinos e impérios africanos",q:"Qual destas é uma fonte arqueológica sobre a África antiga?",a:["Uma escultura de terracota Nok","Um filme de desenho animado","Um livro de ficção científica","Uma reportagem de TV inventada"],c:0,e:"Fonte arqueológica é um objeto real do passado, encontrado em escavações, como as esculturas Nok, moedas de Axum ou pirâmides de Méroe."},
{n:"m",t:"Reinos e impérios africanos",q:"O que significa dizer que um reino cobrava tributos de povos vizinhos?",a:["Que os vizinhos pagavam ao rei com produtos","Que o rei dava presentes aos vizinhos todo ano","Que os vizinhos ensinavam o rei a ler e escrever","Que o rei pagava aos vizinhos para não ser atacado"],c:0,e:"Cobrar tributo é exigir pagamento dos povos dominados — com ouro, gado, colheitas ou trabalho."},
{n:"m",t:"Reino de Cuxe",q:"Qual foi a primeira grande capital do Reino de Cuxe?",a:["Kerma","Méroe","Adúlis","Cairo"],c:0,e:"Kerma foi o primeiro grande centro de Cuxe, muito antigo. Depois vieram Napata e Méroe."},
{n:"m",t:"Reino de Cuxe",q:"Por volta de 730 a.C., os reis de Cuxe...",a:["conquistaram o Egito e se tornaram faraós","foram todos expulsos para o norte da Europa","fundaram a cidade de Roma","descobriram o caminho para a América"],c:0,e:"Os reis cuxitas, como Piye (ou Piankhi) e Taharqa, governaram o Egito como faraós. Esse período ficou conhecido como a 25ª dinastia."},
{n:"m",t:"Reino de Cuxe",q:"O que é o ébano, um dos produtos que Cuxe comerciava?",a:["Uma madeira escura e muito valiosa","Um tipo de peixe grande do rio Nilo","Um tecido macio feito de lã de cabra","Uma pedra usada nas pirâmides"],c:0,e:"Ébano é uma madeira escura, pesada e bonita, usada para fazer móveis e objetos de luxo."},
{n:"m",t:"Reino de Cuxe",q:"Além do comércio, como os cuxitas conseguiam alimento?",a:["Plantando nas margens do Nilo e criando gado","Importando comida congelada de outros países","Pescando só no distante oceano Atlântico","Caçando pinguins nas areias do deserto"],c:0,e:"Os cuxitas plantavam nas terras férteis à beira do Nilo e criavam gado — o gado era sinal de riqueza."},
{n:"m",t:"Reino de Cuxe",q:"Quem acabou com o domínio de Cuxe sobre o Egito, por volta de 660 a.C.?",a:["Os assírios","Os portugueses","Os incas","Os axumitas"],c:0,e:"Os assírios, um povo da Ásia com exército poderoso, invadiram o Egito e empurraram os cuxitas de volta para o sul."},
{n:"m",t:"Candaces",q:"Por que Amanirenas é lembrada como uma rainha guerreira?",a:["Porque liderou o exército de Cuxe contra Roma","Porque venceu todas as corridas de carruagem","Porque fundou a cultura Nok, na Nigéria","Porque derrotou os navios portugueses no mar"],c:0,e:"Amanirenas comandou os cuxitas contra os romanos, que dominavam o Egito. Conta-se até que perdeu um olho em combate."},
{n:"m",t:"Candaces",q:"Qual destas frases sobre as candaces está correta?",a:["Eram rainhas-mães de Cuxe e podiam governar","Eram sacerdotisas que viviam no templo de Roma","Eram escravas dos faraós egípcios","Eram artesãs que faziam esculturas Nok"],c:0,e:"As candaces eram rainhas-mães de Cuxe, com grande poder; algumas governaram sozinhas."},
{n:"m",t:"Candaces",q:"Amanishakheto foi uma candace de Cuxe. Em sua pirâmide, em Méroe, foram encontradas muitas...",a:["joias de ouro","armas de plástico","moedas de papel","esculturas de gelo"],c:0,e:"O tesouro de joias de ouro de Amanishakheto mostra a riqueza e o poder das candaces. Hoje essas joias estão em museus da Alemanha."},
{n:"m",t:"Candaces",q:"O que a existência das candaces nos ensina sobre a história africana?",a:["Que mulheres africanas tiveram poder político","Que só homens governaram reinos na África antiga","Que a África antiga não tinha governo nenhum","Que todas as rainhas africanas eram egípcias"],c:0,e:"As candaces mostram que mulheres africanas governaram, lideraram exércitos e negociaram com impérios, há mais de 2 mil anos."},
{n:"m",t:"Império de Axum",q:"Em que época o Império de Axum começou a se destacar?",a:["Por volta do século I depois de Cristo","No ano 1500, com os portugueses","No século XX, depois das guerras mundiais","Há 10 mil anos, antes da agricultura"],c:0,e:"Axum começou a se destacar por volta do século I d.C. e foi poderoso durante vários séculos."},
{n:"m",t:"Império de Axum",q:"O que era o incenso, produto comerciado por Axum?",a:["Uma resina perfumada queimada em cerimônias","Um metal duro usado para fazer espadas","Um animal do deserto parecido com o camelo","Uma moeda de prata usada pelos romanos"],c:0,e:"Incenso é uma resina de árvores que, ao ser queimada, solta fumaça perfumada. Era muito usada em templos e valia muito."},
{n:"m",t:"Império de Axum",q:"Que produtos Axum comprava de outros povos?",a:["Tecidos, vinho, azeite e vidros","Celulares, carros e computadores","Petróleo, gás natural e carvão","Soja, café e cacau do Brasil"],c:0,e:"Pelo porto de Adúlis chegavam tecidos, vinho, azeite, vidros e objetos de metal vindos do Império Romano, da Arábia e da Índia."},
{n:"m",t:"Império de Axum",q:"Por que as moedas de Axum são importantes para os historiadores?",a:["Mostram os reis e revelam o comércio","Serviam de brinquedo para as crianças","Eram usadas para fazer esculturas Nok","Foram feitas no Brasil e levadas à África"],c:0,e:"As moedas trazem nomes e imagens dos reis e símbolos religiosos. Encontrá-las em lugares distantes mostra até onde ia o comércio de Axum."},
{n:"m",t:"Império de Axum",q:"Depois que o rei Ezana se tornou cristão, o que mudou nas moedas de Axum?",a:["Passaram a ter o símbolo da cruz","Passaram a ser feitas de papel","Deixaram de existir para sempre","Ganharam a imagem de deuses gregos"],c:0,e:"Após a conversão de Ezana, as moedas trocaram os antigos símbolos (como o disco e a lua crescente) pela cruz cristã. ✝️"},
{n:"m",t:"Império de Axum",q:"Qual era a língua e escrita desenvolvida em Axum?",a:["Ge'ez","Latim","Hieróglifos","Português"],c:0,e:"Em Axum se usava o ge'ez, língua e escrita próprias que deram origem a escritas usadas hoje na Etiópia."},
{n:"d",t:"Nok",q:"As esculturas Nok foram feitas há mais de 2 mil anos e resistiram até hoje. Isso foi possível principalmente porque...",a:["o barro cozido no fogo fica duro e resistente","foram guardadas dentro de geladeiras antigas","eram feitas de ouro maciço e muito pesado","foram pintadas com tinta moderna e plástico"],c:0,e:"Ao ser cozida em altas temperaturas, a argila vira terracota, dura e resistente, capaz de durar milhares de anos debaixo da terra."},
{n:"d",t:"Nok",q:"Um agricultor encontra, ao arar a terra na Nigéria, uma cabeça de terracota com olhos triangulares furados. O que ela provavelmente é?",a:["Uma peça da antiga cultura Nok","Uma moeda do Império de Axum","Uma pirâmide do Reino de Cuxe","Uma estátua do imperador Augusto"],c:0,e:"Terracota, Nigéria e olhos triangulares com a pupila furada são marcas típicas da cultura Nok."},
{n:"d",t:"Nok",q:"Hoje, muitas esculturas Nok são retiradas ilegalmente e vendidas no exterior. Por que isso é um problema?",a:["A Nigéria perde parte do seu patrimônio e história","As esculturas ficam muito mais bonitas no exterior","O barro cozido vira pó assim que sai da terra","Elas não valem nada e ninguém quer comprá-las"],c:0,e:"Quando uma peça é arrancada do lugar sem estudo, perdemos pistas sobre como e onde foi usada, e o país perde parte do seu patrimônio."},
{n:"d",t:"Nok",q:"Qual conclusão os arqueólogos podem tirar ao encontrar ferramentas de ferro e restos de plantas cultivadas em aldeias Nok?",a:["Que plantavam usando ferramentas de metal","Que eram nômades e nunca plantavam nada","Que compravam toda a sua comida do Egito","Que viviam só da pesca em navios no mar"],c:0,e:"Ferramentas de ferro + restos de cultivos = povo que plantava, morava em aldeias e dominava a metalurgia."},
{n:"d",t:"Nok",q:"O que a cultura Nok e o Reino de Cuxe (em Méroe) têm em comum?",a:["Os dois dominavam a metalurgia do ferro","Os dois ficavam na atual Nigéria","Os dois foram governados por candaces","Os dois cunhavam moedas de ouro"],c:0,e:"Tanto os Nok quanto os cuxitas de Méroe sabiam produzir ferro. Já as candaces eram só de Cuxe, e as moedas eram de Axum."},
{n:"d",t:"Reinos e impérios africanos",q:"Qual afirmação sobre a África antiga está correta?",a:["Houve reinos com governo, comércio e cidades","O continente só foi habitado depois dos europeus","Todos os povos africanos falavam a mesma língua","Nenhum povo africano conhecia a escrita"],c:0,e:"A África antiga teve reinos e impérios organizados, como Cuxe e Axum, com cidades, comércio e até escritas próprias (meroítica e ge'ez)."},
{n:"d",t:"Reinos e impérios africanos",q:"Para estudar a história de Cuxe, um historiador pode usar inscrições, pirâmides, objetos e textos de outros povos (como egípcios e romanos). Isso mostra que...",a:["a história usa fontes de vários tipos","só os textos escritos servem como fonte","as pirâmides não ajudam a conhecer o passado","os romanos inventaram a história de Cuxe"],c:0,e:"Quanto mais tipos de fontes, melhor: objetos, construções, inscrições e relatos de outros povos se completam para contar a história."},
{n:"d",t:"Reinos e impérios africanos",q:"Por que o controle de rotas de comércio era tão importante para reinos como Cuxe e Axum?",a:["Porque o comércio trazia riqueza e poder","Porque as rotas eram usadas só para passeios","Porque o comércio era proibido nesses reinos","Porque as rotas levavam diretamente à América"],c:0,e:"Quem controla os caminhos por onde passam ouro, marfim e incenso pode cobrar taxas e fazer bons negócios — e assim enriquece."},
{n:"d",t:"Reinos e impérios africanos",q:"Leia: 'O governante dominava vários povos diferentes, que pagavam tributos e obedeciam às suas ordens.' Esse texto descreve...",a:["um império","uma aldeia nômade","uma família","uma escola"],c:0,e:"Dominar vários povos e receber tributos deles é a característica principal de um império."},
{n:"d",t:"Reino de Cuxe",q:"Durante um período, o Egito dominou a Núbia. Depois, Cuxe conquistou o Egito. Isso mostra que a relação entre os dois reinos foi...",a:["ora de comércio, ora de guerra","sempre de paz, sem nenhum conflito","inexistente, pois nunca se encontraram","sempre de domínio do Egito sobre Cuxe"],c:0,e:"Egito e Cuxe comerciaram, guerrearam e se dominaram em épocas diferentes. A história deles é cheia de idas e vindas."},
{n:"d",t:"Reino de Cuxe",q:"Taharqa foi um rei de Cuxe que também governou como faraó. O que isso mostra?",a:["Que Cuxe chegou a dominar o Egito","Que o Egito nunca teve faraós","Que Cuxe ficava na Europa","Que Taharqa era um imperador romano"],c:0,e:"Taharqa foi um dos faraós cuxitas da 25ª dinastia, quando reis de Cuxe governaram o Egito."},
{n:"d",t:"Reino de Cuxe",q:"Por que Méroe era um bom lugar para a produção de ferro?",a:["Tinha minério e madeira para os fornos","Havia neve para esfriar o metal","Os romanos levavam ferro pronto para lá","O ferro caía do céu em dias de chuva"],c:0,e:"Para fazer ferro é preciso minério e muito combustível (madeira/carvão). A região de Méroe tinha os dois, além do rio Nilo para transportar."},
{n:"d",t:"Reino de Cuxe",q:"As pirâmides de Cuxe eram construídas para...",a:["servir de túmulo para reis, rainhas e nobres","guardar os grãos de toda a colheita do ano","servir de moradia para as famílias camponesas","vigiar a chegada de navios romanos"],c:0,e:"Como no Egito, as pirâmides cuxitas eram túmulos da realeza e da elite, ligados à crença na vida após a morte."},
{n:"d",t:"Reino de Cuxe",q:"Qual sequência mostra as capitais de Cuxe na ordem em que surgiram?",a:["Kerma → Napata → Méroe","Méroe → Kerma → Napata","Napata → Méroe → Kerma","Méroe → Napata → Kerma"],c:0,e:"A ordem é Kerma (a mais antiga), depois Napata e, por último, Méroe."},
{n:"d",t:"Reino de Cuxe",q:"O Sudão tem mais pirâmides do que o Egito, mas elas são menos famosas. Uma possível explicação é que...",a:["a história de Cuxe foi menos estudada e divulgada","as pirâmides do Sudão foram feitas há poucos anos","o Sudão fica muito longe, na América do Sul","as pirâmides do Sudão estão debaixo do mar"],c:0,e:"Por muito tempo a história da Núbia foi deixada de lado nos livros, que davam destaque ao Egito. Hoje ela é cada vez mais estudada."},
{n:"d",t:"Candaces",q:"O escritor grego Estrabão contou que a rainha de Cuxe que lutou contra Roma tinha perdido um olho. De que candace ele falava?",a:["Amanirenas","Amanishakheto","Cleópatra","Nefertiti"],c:0,e:"Estrabão descreveu uma rainha corajosa, cega de um olho, que enfrentou os romanos — a candace Amanirenas."},
{n:"d",t:"Candaces",q:"Por que os acordos de paz negociados por Amanirenas com Roma são considerados uma vitória de Cuxe?",a:["Cuxe continuou livre e sem pagar tributos","Cuxe passou a ser uma província de Roma","Amanirenas virou imperatriz dos romanos","Os romanos destruíram todas as pirâmides"],c:0,e:"Cuxe não virou província romana e deixou de pagar tributos. Para um reino enfrentar Roma e sair assim, foi uma grande conquista."},
{n:"d",t:"Candaces",q:"Uma imagem de Cuxe mostra uma mulher grande e forte, com joias, segurando armas e dominando inimigos. Quem ela provavelmente representa?",a:["Uma candace","Uma camponesa","Uma escrava romana","Uma deusa grega"],c:0,e:"As candaces eram representadas como mulheres fortes e poderosas, às vezes vencendo inimigos — símbolos de autoridade e proteção do reino."},
{n:"d",t:"Candaces",q:"Qual destas afirmações compara corretamente as candaces com as rainhas da maioria dos reinos antigos?",a:["Tinham mais poder do que muitas outras rainhas","Não tinham poder nenhum, ao contrário das outras","Eram iguais aos faraós egípcios em tudo","Só existiram em reinos do sul da Europa"],c:0,e:"Em muitos reinos antigos, as rainhas tinham pouco poder político. Em Cuxe, as candaces governavam, guerreavam e negociavam."},
{n:"d",t:"Império de Axum",q:"O profeta persa Mani, no século III, disse que os quatro maiores reinos do mundo eram Roma, Pérsia, China e...",a:["Axum","Nok","Portugal","Inca"],c:0,e:"Mani colocou Axum entre os quatro maiores reinos de sua época. Isso mostra como Axum era rico e respeitado. 🌍"},
{n:"d",t:"Império de Axum",q:"Por volta do ano 350, o rei Ezana atacou Méroe. Qual foi a consequência?",a:["O Reino de Cuxe se enfraqueceu e chegou ao fim","Axum foi totalmente destruído pelos cuxitas","Méroe virou a capital do Império Romano","Ezana se tornou o faraó de todo o Egito"],c:0,e:"A conquista de Méroe por Ezana marcou o fim do antigo Reino de Cuxe, que já estava enfraquecido."},
{n:"d",t:"Império de Axum",q:"A partir do século VII, Axum foi perdendo força. Um dos motivos foi...",a:["perder o controle do comércio no mar Vermelho","a chegada de muitos turistas vindos do Brasil","uma nevasca que cobriu o reino por cem anos","a invenção dos aviões, que substituíram os barcos"],c:0,e:"Com a expansão árabe e islâmica a partir do século VII, Axum perdeu o controle do comércio no mar Vermelho, sua grande fonte de riqueza."},
{n:"d",t:"Império de Axum",q:"Por que dizemos que Axum foi um dos primeiros reinos cristãos do mundo?",a:["O rei Ezana se converteu já no século IV","Jesus Cristo nasceu na cidade de Axum","Os portugueses levaram a religião para lá","Axum inventou a religião cristã"],c:0,e:"O rei Ezana adotou o cristianismo por volta do ano 330, antes de muitos reinos da Europa. A Etiópia tem uma das igrejas cristãs mais antigas do mundo."},
{n:"d",t:"Império de Axum",q:"As estelas de Axum foram talhadas em um único bloco de pedra, algumas com mais de 20 metros. O que isso revela sobre os axumitas?",a:["Tinham técnica e trabalho bem organizado","Não sabiam cortar nem esculpir pedras","Usavam guindastes e máquinas elétricas","Compravam as estelas prontas da Europa"],c:0,e:"Cortar, esculpir, transportar e erguer uma pedra gigante exigia técnica, planejamento e muita gente trabalhando junto, sob um governo forte."},
{n:"f",t:"Nok",q:"O que os Nok faziam com o barro?",a:["Esculturas cozidas no fogo","Moedas para o comércio","Barcos para o rio Nilo","Pirâmides para os reis"],c:0,e:"Os Nok moldavam o barro em forma de cabeças e figuras e depois cozinhavam no fogo, criando a terracota."},
{n:"f",t:"Nok",q:"Os Nok moravam em...",a:["aldeias","navios","castelos","arranha-céus"],c:0,e:"Os Nok viviam em aldeias, onde plantavam e trabalhavam o ferro."},
{n:"f",t:"Nok",q:"Ferramentas como enxadas e machados ajudavam os Nok a...",a:["plantar e cortar madeira","voar e nadar","escrever e ler","pintar e cantar"],c:0,e:"Com enxadas e machados de ferro ficava mais fácil preparar a terra para plantar e cortar árvores. 🪓"},
{n:"f",t:"Nok",q:"As esculturas Nok foram encontradas...",a:["enterradas no solo","no fundo do mar","dentro de pirâmides do Egito","em cavernas de gelo"],c:0,e:"As peças Nok ficaram enterradas por séculos e foram achadas em escavações e por mineradores e agricultores."},
{n:"f",t:"Reinos e impérios africanos",q:"Ouro, sal e marfim eram produtos muito usados no...",a:["comércio antigo","jogo de futebol das aldeias","transporte de carros e motos","cinema e na televisão"],c:0,e:"Esses produtos valiosos eram trocados e vendidos entre povos, enriquecendo reinos e impérios."},
{n:"f",t:"Reinos e impérios africanos",q:"Os povos africanos antigos eram todos iguais?",a:["Não, eram muito diferentes entre si","Sim, todos falavam a mesma língua","Sim, todos obedeciam ao mesmo rei","Sim, moravam na mesma cidade"],c:0,e:"Cada povo africano tinha língua, costumes, crenças e governo próprios. A diversidade é uma marca da África."},
{n:"f",t:"Reinos e impérios africanos",q:"Quem é o historiador?",a:["Quem estuda o passado dos povos","Quem cuida da saúde dos doentes","Quem projeta e constrói as casas","Quem dirige os ônibus da cidade"],c:0,e:"O historiador pesquisa fontes para entender e contar como os povos viviam no passado."},
{n:"f",t:"Reinos e impérios africanos",q:"Cuxe e Axum ficavam em qual parte da África?",a:["Nordeste","Sudoeste","Extremo sul","Centro-oeste"],c:0,e:"Os dois ficavam no nordeste da África: Cuxe no atual Sudão e Axum na atual Etiópia e Eritreia."},
{n:"f",t:"Reino de Cuxe",q:"O Reino de Cuxe é um dos reinos mais antigos de qual continente?",a:["África","Europa","Oceania","América"],c:0,e:"Cuxe é um dos reinos mais antigos da África, vizinho do Egito."},
{n:"f",t:"Reino de Cuxe",q:"Os cuxitas usavam o rio Nilo para...",a:["beber, plantar e transportar mercadorias","esquiar e patinar no gelo do inverno","fazer corridas de lancha com turistas","produzir energia elétrica para as casas"],c:0,e:"O Nilo dava água para beber e irrigar plantações e servia de caminho para barcos com mercadorias."},
{n:"f",t:"Reino de Cuxe",q:"Napata foi...",a:["uma capital de Cuxe","um faraó famoso do Egito","um rio que corta a Nigéria","um deus adorado em Axum"],c:0,e:"Napata foi uma das capitais de Cuxe, entre Kerma (a mais antiga) e Méroe (a última)."},
{n:"f",t:"Reino de Cuxe",q:"O ouro de Cuxe era muito desejado por qual povo vizinho?",a:["Os egípcios","Os incas","Os japoneses","Os vikings"],c:0,e:"Os egípcios queriam muito o ouro da Núbia, usado em joias, objetos dos templos e tesouros dos faraós."},
{n:"f",t:"Reino de Cuxe",q:"Como ficava na Núbia, o Reino de Cuxe também é chamado de reino...",a:["núbio","romano","asteca","grego"],c:0,e:"Como ficava na Núbia, Cuxe é chamado também de reino núbio, e seu povo, de núbios."},
{n:"f",t:"Candaces",q:"Candace era um título que significava algo como...",a:["rainha","soldado","pescador","escravo"],c:0,e:"Candace (ou kandake) era o título das rainhas e rainhas-mães de Cuxe. 👑"},
{n:"f",t:"Candaces",q:"As candaces viviam no reino que tinha Méroe como capital. Que reino era esse?",a:["Cuxe","Axum","Egito","Roma"],c:0,e:"Méroe era a capital de Cuxe, o reino das candaces."},
{n:"f",t:"Candaces",q:"Uma rainha-mãe era...",a:["a mãe do rei","a filha do soldado","a avó do pescador","a irmã do comerciante"],c:0,e:"Rainha-mãe é a mãe do rei. Em Cuxe ela tinha muito poder e prestígio."},
{n:"f",t:"Candaces",q:"As candaces mostram que, em Cuxe, as mulheres...",a:["podiam ocupar o poder","não podiam sair de casa","eram proibidas de falar","não tinham nome"],c:0,e:"Em Cuxe, mulheres podiam ser rainhas poderosas, governar e liderar exércitos."},
{n:"f",t:"Império de Axum",q:"Axum era um...",a:["império africano","país da Europa","rio do Brasil","deus egípcio"],c:0,e:"Axum foi um grande império do nordeste da África, onde hoje ficam a Etiópia e a Eritreia."},
{n:"f",t:"Império de Axum",q:"Adúlis era...",a:["o porto de Axum","um rei de Cuxe","uma escultura Nok","um deus romano"],c:0,e:"Adúlis era o porto de Axum no mar Vermelho, por onde passava o comércio do império. ⚓"},
{n:"f",t:"Império de Axum",q:"Por onde as mercadorias de Axum viajavam até outros povos?",a:["Pelo mar Vermelho, em barcos","Por trens elétricos muito rápidos","Por aviões de carga modernos","Por caminhões nas rodovias"],c:0,e:"Os barcos saíam do porto de Adúlis pelo mar Vermelho, levando e trazendo mercadorias."},
{n:"f",t:"Império de Axum",q:"Hoje, a Etiópia é um país de qual continente?",a:["África","Ásia","Europa","Oceania"],c:0,e:"A Etiópia fica no nordeste da África. Lá estão as ruínas e estelas do antigo Império de Axum."},
{n:"f",t:"Império de Axum",q:"O que os axumitas plantavam nas terras altas?",a:["Cereais, como trigo e cevada","Soja e milho para exportar","Cana-de-açúcar e laranja","Nada, pois não plantavam"],c:0,e:"Os axumitas cultivavam cereais (como trigo, cevada e teff) nas terras altas, às vezes em terraços nas encostas."},
{n:"f",t:"Império de Axum",q:"Ezana foi um...",a:["rei de Axum","faraó do Egito","imperador romano","artista Nok"],c:0,e:"Ezana foi o rei de Axum que adotou o cristianismo e conquistou Méroe, no século IV."},
{n:"m",t:"Nok",q:"Por que as esculturas Nok são importantes para conhecer esse povo?",a:["Porque mostram aparência, enfeites e costumes","Porque trazem textos escritos em hieróglifos","Porque eram usadas como moedas no comércio","Porque mostram mapas dos reinos vizinhos"],c:0,e:"Sem escrita, as esculturas são uma das principais fontes: mostram penteados, joias e talvez crenças dos Nok."},
{n:"m",t:"Nok",q:"A cultura Nok é estudada principalmente por meio de...",a:["vestígios arqueológicos","livros escritos pelos Nok","cartas enviadas aos romanos","filmes antigos"],c:0,e:"Os Nok não deixaram escrita conhecida. Esculturas, fornos e ferramentas encontrados em escavações são as principais fontes."},
{n:"m",t:"Nok",q:"A cultura Nok se desenvolveu perto de qual grande rio africano?",a:["Rio Níger","Rio Nilo","Rio Amazonas","Rio Danúbio"],c:0,e:"A região Nok fica no centro da Nigéria, perto dos rios Níger e Benue. O Nilo fica no nordeste da África."},
{n:"m",t:"Nok",q:"O que significa dizer que os Nok dominavam a metalurgia?",a:["Sabiam transformar minério em metal","Sabiam construir navios muito grandes","Sabiam escrever em placas de pedra","Sabiam domesticar e criar elefantes"],c:0,e:"Metalurgia é a técnica de extrair metal do minério e moldá-lo. Os Nok faziam isso com o ferro."},
{n:"m",t:"Reinos e impérios africanos",q:"Por que egípcios e romanos escreveram sobre Cuxe e Axum?",a:["Porque faziam comércio e guerras com eles","Porque moravam todos na mesma cidade","Porque Cuxe e Axum ficavam na Europa","Porque eram governados pelos Nok"],c:0,e:"Povos que comerciavam e guerreavam com Cuxe e Axum deixaram relatos sobre eles — e esses textos hoje são fontes históricas."},
{n:"m",t:"Reinos e impérios africanos",q:"Qual destas NÃO é uma fonte para estudar a África antiga?",a:["Um desenho animado inventado hoje","Uma moeda de Axum","Uma pirâmide de Méroe","Uma história contada por um griô"],c:0,e:"Fontes históricas vêm do passado ou guardam a memória dele. Um desenho inventado hoje não é fonte sobre a África antiga."},
{n:"m",t:"Reinos e impérios africanos",q:"O comércio entre reinos africanos permitia...",a:["trocar produtos, ideias e costumes","apenas brigas entre os povos","que todos falassem português","que ninguém precisasse plantar"],c:0,e:"Junto com mercadorias viajavam ideias, crenças, técnicas e costumes. O comércio aproximava os povos."},
{n:"m",t:"Reinos e impérios africanos",q:"Leia: 'Nosso rei governa apenas o nosso povo, nesta terra às margens do rio.' Esse governante comanda...",a:["um reino","um império","uma escola","um navio"],c:0,e:"Quem governa só o seu próprio povo e território comanda um reino. Se dominasse vários povos, seria um império."},
{n:"m",t:"Reino de Cuxe",q:"Por que os cuxitas tinham costumes parecidos com os dos egípcios?",a:["Conviveram e trocaram cultura por séculos","Eram, na verdade, soldados romanos","Nunca tiveram contato um com o outro","Vieram juntos da América do Sul"],c:0,e:"Vizinhos por muito tempo, Cuxe e Egito comerciaram, guerrearam e trocaram crenças e costumes."},
{n:"m",t:"Reino de Cuxe",q:"Que deus egípcio também era adorado em Cuxe?",a:["Amon","Zeus","Tupã","Odin"],c:0,e:"Amon era um deus muito importante no Egito e também em Cuxe, que construiu templos para ele, como em Napata."},
{n:"m",t:"Reino de Cuxe",q:"Por que o ferro de Méroe foi importante para Cuxe?",a:["Para armas, ferramentas e comércio","Para construir aviões e carros","Para fazer moedas de papel","Para cobrir as pirâmides de gelo"],c:0,e:"Com ferro, Cuxe fazia armas e ferramentas melhores e ainda tinha um produto valioso para comerciar."},
{n:"m",t:"Reino de Cuxe",q:"O que os faraós cuxitas fizeram no Egito durante seu governo?",a:["Restauraram templos e tradições egípcias","Proibiram a construção de qualquer templo","Mudaram a capital do Egito para Roma","Ensinaram a língua portuguesa aos egípcios"],c:0,e:"Os faraós cuxitas respeitavam a cultura egípcia: restauraram templos e valorizaram antigas tradições, como as pirâmides."},
{n:"m",t:"Reino de Cuxe",q:"Kerma, a primeira grande capital de Cuxe, ficava...",a:["às margens do rio Nilo","no litoral do oceano Atlântico","no meio do deserto, longe de qualquer água","nas montanhas da Etiópia"],c:0,e:"Como todas as capitais de Cuxe, Kerma ficava junto ao rio Nilo, fonte de água e de caminhos para o comércio."},
{n:"m",t:"Candaces",q:"Por que se diz que em Cuxe a linhagem da mãe era importante?",a:["A mãe do rei ajudava a legitimar o filho","Só crianças órfãs podiam ser reis","O pai do rei era sempre um romano","As mães eram proibidas de entrar no palácio"],c:0,e:"Em Cuxe, ser filho de uma rainha-mãe importante ajudava a garantir o trono. A família da mãe tinha muito peso político."},
{n:"m",t:"Candaces",q:"Além de governar, as candaces também participavam de...",a:["cerimônias religiosas","campeonatos de futebol","viagens de avião","aulas de inglês"],c:0,e:"As candaces tinham papel religioso importante e aparecem em templos ao lado de deuses."},
{n:"m",t:"Candaces",q:"A candace Amanirenas enfrentou os romanos, que naquela época dominavam...",a:["o Egito","a Nigéria","a Etiópia","o Brasil"],c:0,e:"Os romanos tinham conquistado o Egito, vizinho de Cuxe, e tentaram avançar para o sul. Foi aí que Amanirenas os enfrentou."},
{n:"m",t:"Candaces",q:"Em que cidade estão as pirâmides de várias candaces e reis de Cuxe?",a:["Méroe","Roma","Adúlis","Lagos"],c:0,e:"Méroe tem um grande cemitério real com dezenas de pirâmides, incluindo as de candaces como Amanishakheto."},
{n:"m",t:"Império de Axum",q:"Por que Axum precisava de um porto como Adúlis?",a:["Para comerciar por mar com outros povos","Para guardar neve durante o verão","Para criar elefantes dentro da água","Para lançar foguetes ao espaço"],c:0,e:"O porto ligava Axum ao mar Vermelho e às rotas de comércio com Roma, Arábia e Índia."},
{n:"m",t:"Império de Axum",q:"A Igreja Ortodoxa Etíope, que existe até hoje, tem raízes em qual antigo império?",a:["Axum","Cuxe","Nok","Inca"],c:0,e:"O cristianismo chegou à Etiópia com o rei Ezana, de Axum, no século IV. A Igreja Etíope é herdeira dessa história."},
{n:"m",t:"Império de Axum",q:"Qual destes produtos vinha da África e era exportado por Axum?",a:["Marfim","Vinho","Azeite","Vidro"],c:0,e:"O marfim vinha dos elefantes africanos e era exportado. Vinho, azeite e vidro eram produtos que Axum importava."},
{n:"m",t:"Império de Axum",q:"O que mostra que Axum era um império poderoso?",a:["Moedas próprias e estelas gigantes","Não ter rei nem governo organizado","Viver isolado, sem contato com ninguém","Não ter cidades, só acampamentos"],c:0,e:"Cunhar moedas e erguer estelas gigantes exigia riqueza, técnica e um governo forte."},
{n:"m",t:"Império de Axum",q:"As estelas de Axum estavam ligadas a quê?",a:["Aos túmulos de reis e nobres","Às pequenas casas dos camponeses","Às feiras de comércio","Aos portos do mar"],c:0,e:"As estelas marcavam a área dos túmulos da realeza e da elite, mostrando poder e prestígio."},
{n:"m",t:"Império de Axum",q:"A escrita ge'ez é importante porque...",a:["é uma escrita africana que ainda é usada","foi inventada pelos romanos para Axum","era usada só pelo povo de Cuxe","sumiu sem deixar nenhum registro"],c:0,e:"O ge'ez nasceu em Axum e continua em uso na Igreja Etíope; dele vêm escritas usadas hoje na Etiópia e na Eritreia."},
{n:"d",t:"Nok",q:"Por que os pesquisadores dizem que ainda não sabemos tudo sobre os Nok?",a:["Não há textos deles e muitas peças foram saqueadas","Os Nok ainda vivem escondidos na floresta","É proibido por lei estudar a história da África","As esculturas são todas falsas, feitas hoje"],c:0,e:"Sem escrita e com muitas peças retiradas sem estudo, faltam pistas. Por isso os arqueólogos continuam pesquisando."},
{n:"d",t:"Nok",q:"Leia as pistas: 'barro cozido', 'olhos triangulares', 'atual Nigéria', 'ferro'. Elas descrevem...",a:["a cultura Nok","o Reino de Cuxe","o Império de Axum","o Egito antigo"],c:0,e:"Terracota, olhos triangulares, Nigéria e ferro são as marcas da cultura Nok."},
{n:"d",t:"Nok",q:"Qual vantagem as ferramentas de ferro tinham sobre as de pedra?",a:["Eram mais fortes e duravam mais","Eram mais leves do que uma pena","Funcionavam sozinhas, sem ninguém","Eram moles e fáceis de dobrar"],c:0,e:"O ferro é mais resistente e pode ser afiado e consertado. Isso tornava o trabalho no campo mais rápido e eficiente."},
{n:"d",t:"Nok",q:"Os Nok viviam onde hoje é a Nigéria; o Reino de Cuxe, onde hoje é o Sudão. O que isso mostra sobre a África antiga?",a:["Havia povos diferentes em várias regiões","Só existia um povo em toda a África","Nok e Cuxe eram o mesmo reino","A África antiga era desabitada"],c:0,e:"Em várias partes da África existiram povos e culturas diferentes ao mesmo tempo, cada um com suas características."},
{n:"d",t:"Nok",q:"Qual destas afirmações sobre os Nok é FALSA?",a:["Eles construíram pirâmides em Méroe","Eles faziam esculturas de terracota","Eles trabalhavam o ferro","Eles viviam onde hoje é a Nigéria"],c:0,e:"As pirâmides de Méroe são do Reino de Cuxe, no Sudão. Os Nok faziam terracota, trabalhavam o ferro e viviam na atual Nigéria."},
{n:"d",t:"Reinos e impérios africanos",q:"Um historiador quer saber o que os egípcios pensavam sobre Cuxe. Qual fonte é mais útil?",a:["Inscrições egípcias que falam de Cuxe","Uma escultura Nok achada na Nigéria","Uma moeda de Axum com o rei Ezana","Um mapa atual das cidades do Brasil"],c:0,e:"Para saber o que os egípcios pensavam, o melhor é ler o que os próprios egípcios escreveram sobre Cuxe."},
{n:"d",t:"Reinos e impérios africanos",q:"Qual alternativa relaciona corretamente o povo e sua característica?",a:["Axum – moedas e estelas","Nok – pirâmides de Méroe","Cuxe – escrita ge'ez","Axum – esculturas de terracota"],c:0,e:"Axum tinha moedas e estelas. As pirâmides de Méroe são de Cuxe; o ge'ez é de Axum; a terracota é dos Nok."},
{n:"d",t:"Reinos e impérios africanos",q:"Candaces, escrita ge'ez e esculturas de terracota pertencem, respectivamente, a...",a:["Cuxe, Axum e Nok","Axum, Nok e Cuxe","Nok, Cuxe e Axum","Cuxe, Nok e Axum"],c:0,e:"Candaces → Cuxe; escrita ge'ez → Axum; esculturas de terracota → Nok."},
{n:"d",t:"Reinos e impérios africanos",q:"Por que estudar reinos como Cuxe e Axum ajuda a combater o preconceito?",a:["Mostra que africanos criaram reinos ricos","Mostra que a África dependia da Europa","Mostra que só o Egito foi importante","Mostra que os africanos não tinham governo"],c:0,e:"Conhecer Cuxe, Axum e Nok mostra que os povos africanos criaram sociedades ricas, com arte, comércio, escrita e tecnologia."},
{n:"d",t:"Reino de Cuxe",q:"Os reis de Cuxe que governaram o Egito construíram pirâmides em sua terra, quando no Egito elas já não eram feitas havia séculos. Isso indica que eles...",a:["valorizavam tradições antigas","odiavam tudo da cultura egípcia","não sabiam construir outra coisa","usavam pirâmides como casas"],c:0,e:"No Egito, as pirâmides tinham deixado de ser feitas havia muito tempo. Os cuxitas retomaram essa tradição e construíram muitas na Núbia."},
{n:"d",t:"Reino de Cuxe",q:"Uma escavação no Sudão encontra fornos, escória e ferramentas de ferro perto de pirâmides pontiagudas. O sítio provavelmente é...",a:["Méroe","Adúlis","Nok","Roma"],c:0,e:"Fornos e escória (ferro) + pirâmides pontudas no Sudão = Méroe, capital de Cuxe."},
{n:"d",t:"Reino de Cuxe",q:"Qual foi a ordem dos acontecimentos?\n(1) Axum conquista Méroe\n(2) Cuxe governa o Egito\n(3) os assírios expulsam os cuxitas do Egito",a:["2, 3, 1","1, 2, 3","3, 2, 1","2, 1, 3"],c:0,e:"Primeiro Cuxe governou o Egito (por volta de 730 a.C.), depois os assírios expulsaram os cuxitas (por volta de 660 a.C.) e, bem mais tarde, Axum conquistou Méroe (por volta de 350 d.C.)."},
{n:"d",t:"Reino de Cuxe",q:"Por que a escrita meroítica é uma prova importante sobre Cuxe?",a:["Mostra que Cuxe criou escrita própria","Prova que Cuxe ficava na Europa","Mostra que Cuxe nunca escreveu nada","Prova que os Nok governavam Cuxe"],c:0,e:"No início Cuxe usava hieróglifos egípcios, mas depois criou a escrita meroítica — sinal de cultura própria e independente."},
{n:"d",t:"Reino de Cuxe",q:"Por que o domínio de Cuxe sobre o Egito é um fato importante para a história da África?",a:["Um reino núbio chegou a governar o Egito","Cuxe era uma província do Império Romano","O Egito ficava, na verdade, na Europa","Cuxe não tinha exército nem soldados"],c:0,e:"Os cuxitas, povo da Núbia, governaram o poderoso Egito como faraós. Isso mostra a força dos reinos africanos ao sul do Egito."},
{n:"d",t:"Reino de Cuxe",q:"Qual característica geográfica ligava Cuxe ao Egito e ao interior da África?",a:["O rio Nilo, usado como caminho","O oceano Atlântico e suas ilhas","As geleiras das altas montanhas","A floresta amazônica e seus rios"],c:0,e:"O Nilo corre do interior da África até o Egito. Era a grande 'estrada' por onde passavam barcos, pessoas e mercadorias."},
{n:"d",t:"Candaces",q:"Em Cuxe, algumas candaces governaram sozinhas, sem um rei ao lado. O que isso revela?",a:["Mulheres podiam ter o poder máximo","O reino ficava sem nenhum governo","Os romanos escolhiam as rainhas","As candaces eram todas estrangeiras"],c:0,e:"Algumas candaces foram as soberanas de Cuxe, com o poder mais alto do reino — algo raro no mundo antigo."},
{n:"d",t:"Candaces",q:"Na Bíblia, no livro de Atos dos Apóstolos, aparece um funcionário que cuidava do tesouro da 'Candace, rainha dos etíopes'. O que isso indica?",a:["Que as candaces eram famosas fora da África","Que as candaces eram personagens inventadas","Que Candace era o nome de um rio da Etiópia","Que as candaces moravam na cidade de Roma"],c:0,e:"Os antigos chamavam a Núbia de 'Etiópia'. A citação mostra que o título de candace era conhecido em outras terras."},
{n:"d",t:"Candaces",q:"Qual frase sobre Amanirenas está correta?",a:["Enfrentou Roma e negociou a paz","Construiu as estelas de Axum","Foi a fundadora da cultura Nok","Converteu Axum ao cristianismo"],c:0,e:"Amanirenas, candace de Cuxe, lutou contra os romanos e negociou a paz. As estelas e o cristianismo são de Axum; a terracota, dos Nok."},
{n:"d",t:"Candaces",q:"Comparando as candaces de Cuxe com o rei Ezana de Axum, qual afirmação é correta?",a:["Governaram reinos do nordeste da África","Viveram na mesma cidade e na mesma época","Foram todos imperadores de Roma","Faziam esculturas de terracota"],c:0,e:"Cuxe (Sudão) e Axum (Etiópia/Eritreia) eram reinos vizinhos do nordeste da África, mas existiram em épocas e cidades diferentes."},
{n:"d",t:"Império de Axum",q:"Moedas de Axum foram encontradas na Índia e na Arábia. O que isso prova?",a:["O comércio de Axum chegava muito longe","A Índia ficava dentro do Império de Axum","As moedas foram levadas por turistas hoje","Axum nunca usou moedas no comércio"],c:0,e:"Moedas viajam com os comerciantes. Achá-las tão longe mostra o alcance das rotas comerciais de Axum. 🪙"},
{n:"d",t:"Império de Axum",q:"Qual conjunto de características pertence ao Império de Axum?",a:["Porto de Adúlis, moedas, estelas e escrita ge'ez","Pirâmides de Méroe, candaces e escrita meroítica","Terracota, olhos triangulares e aldeias na Nigéria","Faraós, hieróglifos e o deus Amon no Egito"],c:0,e:"Adúlis, moedas, estelas e ge'ez são de Axum. Méroe e candaces são de Cuxe; terracota é Nok; faraós e hieróglifos, do Egito."},
{n:"d",t:"Império de Axum",q:"O rei Ezana mandou registrar suas vitórias em inscrições de pedra, em ge'ez e também em grego. Por que usar o grego?",a:["O grego era usado no comércio internacional","Os Nok, vizinhos de Axum, falavam grego","O grego era a língua oficial de Cuxe","Era proibido escrever em ge'ez"],c:0,e:"O grego era uma língua comum nas rotas de comércio do mar Vermelho. Escrever em grego fazia a mensagem chegar a estrangeiros."},
{n:"d",t:"Império de Axum",q:"Por que o mar Vermelho foi importante tanto para o crescimento quanto para a decadência de Axum?",a:["Seu comércio trouxe riqueza; perdê-lo trouxe crise","Ele secou de repente e Axum desapareceu","Nele caiu uma nevasca que destruiu o porto","Ele separava Axum de todo o resto do mundo"],c:0,e:"Controlar o comércio do mar Vermelho enriqueceu Axum; quando perdeu esse controle, a partir do século VII, o império enfraqueceu."},
{n:"d",t:"Império de Axum",q:"Um turista visita hoje a cidade de Axum. O que ele pode ver por lá do antigo império?",a:["Estelas gigantes de pedra","Pirâmides de Méroe","Esculturas Nok no chão","O porto romano de Alexandria"],c:0,e:"Em Axum, na Etiópia, ainda estão de pé estelas gigantes, como o obelisco devolvido pela Itália. São Patrimônio Mundial da UNESCO."}
];
